const meta = $('Contract Uploaded').first().json;
const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
const MAX = 30 * 1024 * 1024;
if (buf.length > MAX) {
  throw new Error(`File too large for Claude PDF input (${(buf.length/1048576).toFixed(1)} MB, limit ~30 MB): ${meta.name}`);
}
const b64 = buf.toString('base64');

const prompt = `You are a contract analyst. Read the attached contract (it may be scanned; read it visually if needed).
Return ONLY a valid JSON object. No markdown, no commentary. Use null when a field is not stated.
Dates must be YYYY-MM-DD. If the contract has an initial term plus automatic renewal terms, "end_date" is the end of the CURRENT/initial term.
Fields:
{
  "vendor": string,
  "contract_type": string (e.g. SaaS, lease, services, NDA, supply),
  "start_date": string|null,
  "end_date": string|null,
  "auto_renew": boolean|null,
  "renewal_term_months": number|null,
  "notice_period_days": number|null (days of written notice required before end_date to cancel/avoid renewal),
  "annual_cost": number|null (annualise if billed monthly/quarterly),
  "currency": string|null (ISO code),
  "penalty_clause": string|null (early termination / late cancellation penalty, max 25 words),
  "summary": string (max 2 sentences),
  "confidence": "high"|"medium"|"low" (how sure you are about end_date, auto_renew and notice_period_days),
  "review_reason": string|null (what is unclear, if anything)
}`;

return [{
  json: {
    file_id: meta.id,
    file_name: meta.name,
    file_link: meta.webViewLink || '',
    body: {
      model: 'claude-sonnet-5-5',
      max_tokens: 1500,
      messages: [{
        role: 'user',
        content: [
          { type: 'document', source: { type: 'base64', media_type: 'application/pdf', data: b64 } },
          { type: 'text', text: prompt }
        ]
      }]
    }
  }
}];

const meta = $('Prepare Claude Request').first().json;
const res = $input.first().json;
const today = new Date().toISOString().slice(0, 10);

const row = {
  file_id: meta.file_id, file_name: meta.file_name, file_link: meta.file_link,
  vendor: '', contract_type: '', start_date: '', end_date: '', auto_renew: '',
  notice_period_days: '', annual_cost: '', currency: '', penalty_clause: '',
  summary: '', status: 'needs_review', review_reason: '', added_on: today
};

try {
  if (res.error) throw new Error('Claude API error: ' + (res.error.message || JSON.stringify(res.error)));
  const text = (res.content || []).filter(c => c.type === 'text').map(c => c.text).join('');
  if (!text) throw new Error('Empty response from Claude');
  const start = text.indexOf('{'), end = text.lastIndexOf('}');
  if (start < 0 || end < 0) throw new Error('No JSON found in response');
  const d = JSON.parse(text.slice(start, end + 1));

  row.vendor = d.vendor ?? '';
  row.contract_type = d.contract_type ?? '';
  row.start_date = d.start_date ?? '';
  row.end_date = d.end_date ?? '';
  row.auto_renew = d.auto_renew === null || d.auto_renew === undefined ? '' : String(d.auto_renew);
  row.notice_period_days = d.notice_period_days ?? '';
  row.annual_cost = d.annual_cost ?? '';
  row.currency = d.currency ?? '';
  row.penalty_clause = d.penalty_clause ?? '';
  row.summary = d.summary ?? '';

  const problems = [];
  if (!row.end_date || isNaN(new Date(row.end_date))) problems.push('end_date missing or invalid');
  if (d.confidence === 'low') problems.push('low confidence');
  if (d.review_reason) problems.push(d.review_reason);
  if (problems.length) {
    row.review_reason = problems.join('; ');
  } else {
    row.status = 'ok';
  }
} catch (e) {
  row.review_reason = String(e.message || e).slice(0, 300);
}
return [{ json: row }];

const RANK = { NONE: 0, LOW: 1, MEDIUM: 2, HIGH: 3 };
const today = new Date(); today.setHours(0, 0, 0, 0);
const num = v => { const n = parseFloat(String(v ?? '').replace(/[^0-9.\-]/g, '')); return isNaN(n) ? null : n; };
const out = [];

for (const item of $input.all()) {
  const r = item.json;
  if (!r.file_id) continue;
  if (String(r.status || '').toLowerCase() !== 'ok') continue;   // skip needs_review / ignored rows
  const end = new Date(r.end_date);
  if (isNaN(end)) continue;
  end.setHours(0, 0, 0, 0);

  const daysLeft = Math.round((end - today) / 86400000);
  if (daysLeft < 0) continue;                                      // already ended

  const notice = num(r.notice_period_days) ?? 30;
  const toDeadline = daysLeft - notice;                            // days left to cancel
  if (toDeadline > 60) continue;                                   // not in the 60-day window yet

  const level = toDeadline <= 7 ? 'HIGH' : (toDeadline <= 30 ? 'MEDIUM' : 'LOW');
  const last = String(r.last_alert_level || 'NONE').toUpperCase();
  const lastDate = r.last_alert_date ? new Date(r.last_alert_date) : null;
  const daysSince = lastDate && !isNaN(lastDate) ? Math.floor((today - lastDate) / 86400000) : 9999;

  const escalated = RANK[level] > (RANK[last] ?? 0);
  const highReminder = level === 'HIGH' && daysSince >= 7;
  if (!escalated && !highReminder) continue;                       // already alerted at this level

  out.push({ json: {
    file_id: r.file_id, file_name: r.file_name, file_link: r.file_link,
    vendor: r.vendor, contract_type: r.contract_type, end_date: r.end_date,
    auto_renew: /^(true|yes|1)$/i.test(String(r.auto_renew)),
    notice_period_days: notice, annual_cost: num(r.annual_cost), currency: r.currency || '',
    penalty_clause: r.penalty_clause || '',
    days_left: daysLeft, days_to_cancel_deadline: toDeadline, urgency: level
  }});
}
return out;

const items = $input.all().map(i => i.json);
items.sort((a, b) => a.days_to_cancel_deadline - b.days_to_cancel_deadline);
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const color = { HIGH: '#c0392b', MEDIUM: '#d68910', LOW: '#2e86c1' };

const atRisk = {};
for (const r of items) {
  if (r.auto_renew && r.annual_cost) atRisk[r.currency || '?'] = (atRisk[r.currency || '?'] || 0) + r.annual_cost;
}
const riskText = Object.entries(atRisk).map(([c, v]) => `${Math.round(v).toLocaleString('en-US')} ${c}`).join(' + ');

const rows = items.map(r => {
  const missed = r.days_to_cancel_deadline < 0;
  const deadlineText = missed ? `<b style="color:#c0392b">MISSED ${Math.abs(r.days_to_cancel_deadline)}d ago</b>` : `<b>${r.days_to_cancel_deadline} days</b>`;
  return `<tr>
<td>${esc(r.vendor)}</td><td>${esc(r.contract_type)}</td><td>${esc(r.end_date)} (${r.days_left}d)</td>
<td>${r.auto_renew ? 'Yes' : 'No'}</td>
<td>${r.annual_cost ? Math.round(r.annual_cost).toLocaleString('en-US') + ' ' + esc(r.currency) : '-'}</td>
<td>${r.notice_period_days}d</td><td>${deadlineText}</td>
<td style="color:${color[r.urgency]}"><b>${r.urgency}</b></td>
<td>${esc(r.penalty_clause) || '-'}</td>
<td><a href="${esc(r.file_link)}">Open</a></td></tr>`;
}).join('');

const html = `<div style="font-family:Arial,sans-serif">
<h2>Contract Renewal Watchdog</h2>
<p><b>${items.length}</b> contract(s) need a decision.${riskText ? ` Auto-renewing spend at risk: <b>${riskText}</b>.` : ''}</p>
<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse;font-size:13px">
<tr style="background:#f2f3f4"><th>Vendor</th><th>Type</th><th>Ends</th><th>Auto-renew</th><th>Annual cost</th><th>Notice</th><th>Cancel deadline in</th><th>Urgency</th><th>Penalty</th><th>File</th></tr>
${rows}</table>
<p style="color:#7f8c8d;font-size:12px">You get a new alert only when urgency increases (LOW &rarr; MEDIUM &rarr; HIGH), and a weekly reminder while HIGH.</p></div>`;

return [{ json: { html, count: items.length } }];

const today = new Date().toISOString().slice(0, 10);
return $('Find Upcoming Renewals').all().map(i => ({ json: {
  file_id: i.json.file_id,
  last_alert_level: i.json.urgency,
  last_alert_date: today
}}));

const e = $json;
const html = `<div style="font-family:Arial,sans-serif"><h3>Workflow failed: ${e.workflow?.name ?? ''}</h3>
<p><b>Node:</b> ${e.execution?.lastNodeExecuted ?? ''}</p>
<p><b>Error:</b> ${String(e.execution?.error?.message ?? '').replace(/</g, '&lt;')}</p>
<p><a href="${e.execution?.url ?? '#'}">Open execution</a></p></div>`;
return [{ json: { html, name: e.workflow?.name ?? 'workflow' } }];
